import {interpolate,celsius} from './calc.js';
import {KEY,addRecord,deleteRecord,readRecords} from './history.js';
const $=id=>document.getElementById(id);
const pressure=[['bara','bar(a)',1,0],['barg','bar(g)',1,1.01325],['kPa','kPa(a)',.01,0],['MPa','MPa(a)',10,0],['psia','psia',.06894757293168,0],['psig','psig',.06894757293168,1.01325],['kgfa','Kg/cm2(a)',.980665,0]],temperature=[['C','°C'],['F','°F'],['K','K']];
const units=[...pressure,...temperature],unitLabel=u=>units.find(d=>d[0]===u)?.[1]||u;
const fmt=n=>n.toLocaleString('en-US',{maximumFractionDigits:4}),fixed=n=>n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const title=r=>r.mode==='pt'?'Saturation temperature':'Saturation pressure',inputTitle=r=>r.mode==='pt'?'Pressure':'Temperature';
const dateLabel=r=>new Date(r.date).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'medium'});
const tempFromC=(n,u)=>u==='F'?n*9/5+32:u==='K'?n+273.15:n;
const options=(el,list)=>{el.replaceChildren(...list.map(([v,l])=>{const o=document.createElement('option');o.value=v;o.textContent=l;return o}))};
let records=[],current=null,selected=null,shareRecord=null;
try{records=readRecords(localStorage).filter(r=>(r.mode==='pt'?pressure:temperature).some(u=>u[0]===r.inputUnit)&&(r.mode==='pt'?temperature:pressure).some(u=>u[0]===r.outputUnit))}catch{$('storage-note').textContent='History is unavailable in browser storage. New conversions will be kept for this session.'}
function save(){try{localStorage.setItem(KEY,JSON.stringify(records))}catch{$('storage-note').textContent='History could not be saved to this browser. It is available for this session only.'}renderHistory()}
function resultValue(r){if(r.mode==='pt')return tempFromC(r.t,r.outputUnit);const u=pressure.find(d=>d[0]===r.outputUnit);return (r.p-u[3])/u[2]}
function summary(r){return `${fmt(r.input)} ${unitLabel(r.inputUnit)} → ${fixed(resultValue(r))} ${unitLabel(r.outputUnit)}`}
function report(r){return `Ammonia Saturation Condition\n${dateLabel(r)}\n\nInput — ${inputTitle(r)}: ${fmt(r.input)} ${unitLabel(r.inputUnit)}\nOutput — ${title(r)}: ${fixed(resultValue(r))} ${unitLabel(r.outputUnit)}\n\nTable interpolation\n${[r.inputUnit,r.outputUnit].some(u=>['barg','psig'].includes(u))?'Gauge reference: 1.01325 bar atmospheric pressure.\n':''}`}
function updateRange(){const pt=$('mode').value==='pt',unit=$('unit').value;let lo,hi,label;if(pt){const u=pressure.find(d=>d[0]===unit);lo=(.386-u[3])/u[2];hi=(113-u[3])/u[2];label=u[1]}else{lo=tempFromC(-51.1,unit);hi=tempFromC(132,unit);label=unitLabel(unit)}$('range').textContent=`Range: ${fmt(lo)} to ${fmt(hi)} ${label}`;$('gauge-note').hidden=![unit,$('output-unit').value].some(u=>u==='barg'||u==='psig')}
function clearResult(){$('results-link').setAttribute('aria-disabled','true');current=null;$('output-panel').hidden=true;$('workspace').classList.remove('has-result');$('error').hidden=true;$('status').textContent='';updateRange()}
function setup(){const pt=$('mode').value==='pt';$('input-heading').textContent=pt?'Pressure':'Temperature';$('value').setAttribute('aria-label',pt?'Pressure value':'Temperature value');$('value').value='';options($('unit'),pt?pressure:temperature);options($('output-unit'),pt?temperature:pressure);clearResult()}
function renderResult(){if(!current)return;$('results-link').setAttribute('aria-disabled','false');$('output-panel').hidden=false;$('workspace').classList.add('has-result');$('result-heading').textContent=title(current);$('result').textContent=fixed(resultValue(current));$('result-time').textContent=new Date(current.date).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'});updateRange()}
function element(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
function button(text,fn,cls='soft'){const b=element('button',text,cls);b.type='button';b.onclick=fn;return b}
function card(r,withDelete){const row=element('div',undefined,'history-row'),b=button('',()=>showDetail(r.id),'history-card');const heading=element('strong',title(r));heading.append(element('em','View →'));b.append(heading,element('small',dateLabel(r)),element('span',summary(r)));row.append(b);if(withDelete){const del=button('Delete',()=>remove(r.id),'danger');del.setAttribute('aria-label',`Delete conversion from ${dateLabel(r)}`);row.append(del)}return row}
function renderHistory(){$('delete-all').disabled=!records.length;$('history-list').replaceChildren(...records.map(r=>card(r,true)));if(!records.length)$('history-list').append(element('p','No saved conversions yet.','empty'))}
function revealHistory(){ $('history-dialog').hidden=false;$('history-open').setAttribute('aria-expanded','true');$('history-title').focus({preventScroll:true});$('history-dialog').scrollIntoView({behavior:'smooth',block:'start'}) }
function closeHistory(){ $('history-dialog').hidden=true;$('history-open').setAttribute('aria-expanded','false');$('history-open').focus({preventScroll:true}) }
function openHistory(){selected=null;$('history-detail').hidden=true;$('history-list').hidden=false;$('history-status').textContent='';renderHistory();revealHistory()}
function remove(id){records=deleteRecord(records,id);save();if(selected===id)openHistory();$('history-status').textContent='Conversion deleted.'}
function showDetail(id){const r=records.find(r=>r.id===id);if(!r)return;selected=id;revealHistory();$('history-list').hidden=true;$('history-detail').hidden=false;const detail=$('history-detail');detail.replaceChildren();const actions=element('div',undefined,'actions');actions.append(button('← All history',openHistory),button('Load conversion',()=>load(r)),button('Delete',()=>remove(r.id),'danger'));detail.append(actions,element('h3',title(r)),element('p',dateLabel(r),'hint'));for(const [label,value] of [[inputTitle(r),`${fmt(r.input)} ${unitLabel(r.inputUnit)}`],[title(r),`${fixed(resultValue(r))} ${unitLabel(r.outputUnit)}`]]){const row=element('div',undefined,'detail-row');row.append(element('span',label),element('strong',value));detail.append(row)}const exports=element('div',undefined,'actions');exports.append(button('Share results',()=>openShare(r)),button('Download CSV',()=>download(r,'csv')),button('Download text',()=>download(r,'txt')));detail.append(exports);$('history-status').textContent=''}
function load(r){$('mode').value=r.mode;setup();$('value').value=r.input;$('unit').value=r.inputUnit;$('output-unit').value=r.outputUnit;current={...r};renderResult();closeHistory();window.dispatchEvent(new CustomEvent('fieldkit:result'))}
function openShare(r){shareRecord={...r};$('share-text').value=report(r);$('share-status').textContent='';$('native-share').hidden=typeof navigator.share!=='function';$('share-dialog').showModal()}
function download(r,type){const quote=v=>'"'+String(v).replaceAll('"','""')+'"';const body=type==='txt'?report(r):[['Date (ISO)','Input property','Input value','Input unit','Output property','Output value','Output unit'],[r.date,inputTitle(r),r.input,unitLabel(r.inputUnit),title(r),resultValue(r),unitLabel(r.outputUnit)]].map(row=>row.map(quote).join(',')).join('\r\n');const blob=new Blob([type==='csv'?'\uFEFF':'',body],{type:type==='csv'?'text/csv;charset=utf-8':'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`ammonia-${r.mode}-${r.date.replace(/[:.]/g,'-')}.${type}`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('status').textContent='Download prepared.';document.querySelectorAll('details[open]').forEach(d=>d.open=false)}
$('mode').onchange=setup;$('unit').onchange=clearResult;$('value').oninput=clearResult;$('clear').onclick=setup;
$('output-unit').onchange=()=>{if(!current)return;current.outputUnit=$('output-unit').value;records=records.map(r=>r.id===current.id?{...current}:r);save();renderResult()};
$('form').onsubmit=e=>{e.preventDefault();clearResult();try{if(!$('value').value.trim())throw Error('Enter a value to calculate.');if(!/^[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?$/.test($('value').value.trim()))throw Error('Enter a valid number.');const input=Number($('value').value),mode=$('mode').value,inputUnit=$('unit').value;let value=input;if(mode==='pt'){const u=pressure.find(d=>d[0]===inputUnit);value=value*u[2]+u[3]}else value=celsius(value,inputUnit);const p=interpolate(value,mode==='pt'?'p':'t');current={id:crypto.randomUUID(),date:new Date().toISOString(),mode,input,inputUnit,outputUnit:$('output-unit').value,t:p.t,p:p.p};records=addRecord(records,{...current});save();renderResult();window.dispatchEvent(new CustomEvent('fieldkit:result'))}catch(e){$('error').textContent=e.message;$('error').hidden=false}};
$('history-open').onclick=openHistory;$('history-close').onclick=()=>closeHistory();$('delete-all').onclick=()=>{records=[];save();openHistory();$('history-status').textContent='All conversions deleted.'};
$('share').onclick=()=>current&&openShare(current);$('share-close').onclick=()=>$('share-dialog').close();$('copy-share').onclick=async()=>{try{await navigator.clipboard.writeText($('share-text').value);$('share-status').textContent='Results copied. Paste them into your message.'}catch{$('share-text').focus();$('share-text').select();$('share-status').textContent='Select and copy the summary above.'}};
$('native-share').onclick=async()=>{try{await navigator.share({title:'Ammonia Saturation Condition result',text:report(shareRecord)});$('share-status').textContent='Share completed.'}catch(e){$('share-status').textContent=e.name==='AbortError'?'Sharing cancelled.':'Sharing is unavailable. Use Copy results.'}};
$('download-csv').onclick=()=>current&&download(current,'csv');$('download-txt').onclick=()=>current&&download(current,'txt');
setup();renderHistory();

$('toggle-sign').onclick=()=>{const input=$('value');input.value=input.value.startsWith('-')?input.value.slice(1):'-'+input.value;clearResult();input.focus();};
